"""Serialize the authored BOM questions and explicit field groups, not templates."""
import json
import re
from pathlib import Path

RUN = Path(__file__).resolve().parent
def refs(*nums):
    return [f'SRC-{i:03d}' for i in nums]

def build():
    source_rows = [
        ('Bills of materials and formulas','Microsoft','https://learn.microsoft.com/en-us/dynamics365/supply-chain/production-control/bill-of-material-bom','2025-07-10','BOM views, version applicability, approval and subordinate references; vendor-specific implementation evidence.'),
        ('About BOM Quantity','Autodesk','https://help.autodesk.com/cloudhelp/2023/ENU/Inventor-Help/files/GUID-37BA8DB6-E39C-4C96-AAF1-E7B342F20D0E.htm','Inventor 2023','Selected indexed quantity documentation; counts, unit amounts and overrides, not a universal calculation algorithm.'),
        ('BOMRow Object','Autodesk','https://help.autodesk.com/cloudhelp/2023/ENU/Inventor-API/files/BOMRow.htm','Inventor 2023 API','Public property table: definitions, occurrences, merged and promoted rows; no adapter executed.'),
        ('Electronics Bill of materials','Autodesk','https://help.autodesk.com/cloudhelp/ENU/Fusion-ECAD/files/ECD-BOM-CPT.htm','Public page inspected 2026-09-07','Electronics designators, footprints and flattened naming; not mandatory mechanical-BOM fields.'),
        ('Recursiveness Check','SAP','https://help.sap.com/docs/SAP_ERP/43fa3cddb00348beb3ed12212a94448f/dd05c453f57eb44ce10000000a174cb4.html','ERP 6.0 EHP8','Indexed text only; direct opening returned empty shell. Group graph versus selected variant and bounded expansion.'),
        ('Managed model-based 3D engineering','ISO','https://www.iso.org/standard/84300.html','ISO 10303-242:2025 edition 4 public scope only','Candidate engineering structure alignment; licensed clauses and executable mappings uninspected.'),
        ('Configuration Management','NASA','https://www.nasa.gov/reference/6-5-configuration-management/','Handbook chapter 6.5 inspected 2026-09-07','Selected baseline and change-control guidance; domain-specific, not universal governance requirements.'),
        ('PROV-DM','W3C','https://www.w3.org/TR/prov-dm/','Recommendation 2013-04-30','Selected attribution and derivation concepts; does not grant access or certify assertions.'),
        ('Date and Time on the Internet: Timestamps','IETF','https://www.rfc-editor.org/rfc/rfc3339','RFC 3339, July 2002','Seconds and explicit offset; timestamps are not collision-proof identities or interval definitions.'),
    ]
    sources = [dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type='standard' if i in (6,8,9) else 'first-party-doc',primary_source=True,authority_tier=1 if i in (6,8,9) else 2,accessed_at='2026-09-07T13:59:00Z',relevance=r) for i,(t,o,u,v,r) in enumerate(source_rows,1)]
    sections = re.split(r'(?m)^### ',(RUN/'question-design.md').read_text(encoding='utf-8'))[1:]
    assert len(sections)==12
    ids=['bom-baseline','component-occurrence','quantity-basis','assembly-graph','line-effectivity','component-selection','nominal-properties','functional-contribution','composition-change','realization-handoff','composition-stewardship','exchange-fidelity']
    sr=[refs(1,6,7),refs(3,4,6),refs(1,2),refs(1,3,5),refs(1,7,9),refs(1,4),refs(2,4,6,8),refs(6,7,8),refs(1,7,8),refs(1,3,7,8),refs(7,8),refs(3,4,6,8)]
    kinds=[['identity','authority','quality'],['relationship','composition','spatial'],['measurement','provenance','exception'],['composition','validation','quality'],['temporal','decision','lifecycle'],['constraint','evidence','state'],['definition','classification','measurement'],['relationship','constraint','evidence'],['authority','relationship','lifecycle'],['interoperability','decision','event'],['ownership','access','retention'],['provenance','interoperability','validation']]
    layers=[]
    for i,section in enumerate(sections):
        heading,body=section.split('\n',1)
        qtext,fields=body.split('Candidate fields:',1)
        questions=re.findall(r'(?m)^- (.+\?)$',qtext)
        groups=re.findall(r'([a-z][a-z-]*)\s*\{([^}]+)\}',' '.join(fields.split('Sources:',1)[0].split()))
        assert len(questions)==len(groups)==3,(heading,groups)
        lid=ids[i]
        elements=[dict(id=lid+'-'+k,name=k,description='Proposed structured field group: '+d+'. Preserve explicit unknowns and referenced master authority; executable nested schema is deferred.',value_kind='object',cardinality='1',required=True,source_refs=sr[i]) for k,d in groups]
        description='Proposed engineering-composition record for '+heading.lower()+'. Preserve declared view, exact revisions and evidence; no as-built or certification inference.'
        finding=dict(id=lid+'-record',name=heading+' record',description=description,source_refs=sr[i],questions=[dict(id=lid+f'-q{n+1:02d}',text=q,kind=kinds[i][n],answer_data=[elements[n]['id']]) for n,q in enumerate(questions)],data_elements=elements,artifacts=[dict(id=lid+'-evidence',name=heading+' evidence',description='Revision-bound evidence references and receipts for '+heading.lower()+', without copying protected masters.',media_or_form=['application/json','application/yaml','text/markdown','external reference'],serial=True,identity_strategy='Authoritative master-system ID first, then issuer-qualified UUID; revision and exact-byte digest separately. Timestamp alone is not identity.',source_refs=sr[i])],inline_only_rationale=None)
        layers.append(dict(id=lid,name=heading,description=description,source_refs=sr[i],findings=[finding]))
    bundle_names=['Composition authority','Quantified assembly graph','Applicability and selection','Intended characteristics','Change and realization boundary','Governed composition exchange']
    bundles=[dict(id='bom-'+re.sub('[^a-z]+','-',n.lower()).strip('-'),name=n,description='Engineering composition concerns: '+n.lower()+'.',rationale='Subject-specific grouping of two authored records, separating reusable intent from installed reality.',source_refs=sorted(set(s for l in layers[i*2:i*2+2] for s in l['source_refs'])),layers=layers[i*2:i*2+2]) for i,n in enumerate(bundle_names)]
    model=dict(registry_id='vr.wm-obj-019',model_id='WM-OBJ-019',name='Component Type / Engineering BOM',entry_kind='aggregate',purpose='Describe reusable type-level engineering composition distinctly from as-built assembly.',scope_statement='An engineering BOM revision owns occurrence relationships, quantities, applicability, selection, intended-property references and controlled exchange. Product types, designs, configured variants and physical items retain independent masters.',in_scope=['Versioned engineering baseline and component occurrences','Quantities, graph integrity, effectivity and selection','Qualified nominal properties, functional contributions and governed change'],out_of_scope=['As-built item state, actual material consumption and inventory','Production routes, procurement execution and software BOM','Automatic physical action or certification from information validity'],boundary_notes=[dict(neighbor=n,distinction=d,source_refs=s) for n,d,s in [('WM-OBJ-002 Product Type / Catalog Item','Frozen COMPOSE relation: occurrences reference reusable component types, not copied product masters.',refs(1,6)),('WM-OBJ-018 Engineering Design / Product Definition','Design geometry and functional intent stay referenced, not remastered in the BOM.',refs(6,7)),('WM-OBJ-017 Product Configuration / Variant','Selection binds applicability; candidate lines do not imply installed components.',refs(1,4)),('Physical items and manufacturing masters','Engineering occurrence is not serialized item; manufacturing additions and process recursion require a separate view.',refs(1,5))]])
    services=dict(
        dimension=dict(owner_package_requirements=['Identify Dimension owner and composition authority.','Declare namespaces and component/BOM master registries.','Declare delegated release, federation, access and retention policies.'],namespace_guidance='Issuer-qualified BOM IDs with immutable revisions and local occurrence IDs; displayed row numbers and filenames are not master identity.',registry_links=['Dimension model registry','Component type registry','Engineering baseline registry','Change and evidence registry']),
        canon_and_patch=dict(canonicalization_rules=['Preserve distinct occurrences, pinned revisions, engineering view and explicit unknowns.','A flattened projection never overwrites authoritative occurrence topology.'],patch_rules=['Authorized append-only revision or namespaced extension with expected-base digest; reject concurrent conflicts.','Reassess quantities, applicability, selection and where-used impact before release.'],compatibility_rules=['Changed engineering meaning requires a controlled revision, not silent replacement.','Preserve prior versions and explicit cross-view loss; deviations have bounded authority and applicability.']),
        artifact_rules=dict(identity_priority=['Authoritative master-system ID','Governed issuer-qualified UUID','Dimension UUID with revision and digest'],timestamp_rule='RFC 3339 with seconds and UTC Z or numeric offset; distinguish recorded, approved and effective time.',serial_naming_rule='Evidence type plus opaque master ID and revision; dates alone are insufficient.',integrity_rule='Verify exact-byte digests and pinned dependencies. Never execute imported formulas, scripts, macros or instructions automatically.'),
        policies=['Information validity is not physical fit, safety, certification or authority to manufacture.','Do not sum alternatives or propagate incompatible units; incomplete and withheld branches remain explicit.','Vendor examples motivate proposed fields, not universal normative compliance.'],
        crud=dict(read=['Read AGENTS.md and owner policy; resolve baseline/view/context before traversing authorized component references.'],create=['Reuse the active authorized Dimension and existing product masters; create explicit partial engineering composition with stable occurrence IDs.'],update=['Apply expected-base checks and change review; preserve release history and reverse dependency impact.'],delete=['Retire first; respect retention and legal hold, dependent interpretation and authorized deletion. Preserve a minimized tombstone.']),
        roles=[dict(name=n,responsibilities=[r]) for n,r in [('Dimension owner','Defines namespace, storage and delegated access.'),('Composition authority','Owns baseline and approves applicability and change.'),('Engineering author','Maintains component bindings, quantities and evidence.'),('Reviewer','Checks selection, units, cycles and unresolved assertions.'),('Custodian','Preserves authorized readable dependencies without becoming owner.')]],
        access=dict(default_rule='Deny unless owning Dimension authorizes the exact scope and purpose.',scopes=['bundle','layer','finding','artifact'],exceptions=['Explicit time-limited delegated exception only; no privilege inheritance from component containment.'],audit_requirements=['Record actor, purpose, scope, baseline, decision and disclosure receipt without secrets.']),
        agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension owner and access policy','Pinned BOM baseline and view','Selection/effectivity and component dependencies','Evidence, validation and change rules']))
    fnrows=[
        ('resolve-bom','Resolve applicable baseline','Resolve one engineering baseline under explicit context, preserving ambiguity.',['BOM identity','Applicability context'],['Pinned baseline or unresolved outcome'],['Authorized access and declared resolver'],['Never silently select latest'],refs(1,7)),
        ('expand-composition','Expand bounded composition','Traverse occurrences without flattening identity or looping.',['Pinned graph','Selection context'],['Expanded paths and completeness report'],['Pinned dependencies and bounded traversal policy'],['Stop on unresolved branch or cycle; no manufacturing recursion solver implied'],refs(1,3,5)),
        ('qualify-quantity','Qualify engineering quantities','Describe dimensional calculation and override provenance; this contract supplies no calculation engine.',['Occurrence quantities','Units and parent basis'],['Qualified totals or explicit unknowns'],['Compatible units and declared conversion/rounding policy'],['Do not count excluded alternatives or manufacturing scrap as intrinsic composition'],refs(1,2)),
        ('select-components','Bind configured selection','Record constrained choices and qualified substitutions.',['WM-OBJ-017 selection','Component evidence'],['Selected occurrence set and open conflicts'],['Approved applicable choices and interface evidence'],['No universal interchangeability or installation inferred'],refs(1,4)),
        ('review-bom-change','Review and release composition change','Assess where-used impact and baseline authority.',['Proposed revision','Expected base','Reviewer findings'],['Release decision and affected references'],['No unresolved blocking conflict; approver authorized'],['Keep history, deviations and unknown downstream consumers visible'],refs(1,7,8)),
        ('exchange-bom','Exchange composition with loss report','Preserve source identity through target-view mappings.',['Source baseline','Authorized target profile'],['Derivative artifact, mapping and loss report'],['Disclosure permission and tested mapping criteria'],['Reject required unsupported semantics; never overwrite source with projection'],refs(3,4,6,8)),
    ]
    functions=[dict(zip(['id','name','description','inputs','outputs','preconditions','effects','source_refs'],r)) for r in fnrows]
    composition=[dict(target=t,relation=r,purpose=p,required=req,source_refs=s) for t,r,p,req,s in [('WM-OBJ-002','COMPOSE','Frozen type-level component composition relation.',True,refs(1,6)),('WM-OBJ-018','REFERENCE','Resolve controlled geometry and intended definition.',False,refs(6,7)),('WM-OBJ-017','REFERENCE','Bind selected variants without merging lifecycles.',False,refs(1,4)),('WM-OBJ-001','REFERENCE','Link as-built discrepancies without treating intent as observation.',False,refs(1,6)),('Manufacturing BOM, routing and procurement masters','REFERENCE','Preserve independent realization views and permissions.',False,refs(1)),('ISO 10303-242:2025 public scope','ALIGN','Candidate exchange alignment only; licensed clauses and crosswalk deferred.',False,refs(6))]]
    omissions=['No independent external research/review: Claude and Grok each timed out once. Codex-only owner waiver requires reviewable-draft assurance.','SAP support is indexed text only; licensed ISO clauses unread. Source-to-field normative compliance is not established.','Vendor documentation is selected and domain-specific, not exhaustive industry coverage. Alternate/substitute rules are proposed Vercy design needing specialist review.','Nested field groups are not an executable instance schema. No BOM solver, unit engine, CAD adapter or real-product round-trip fixtures delivered.','Actual physical properties and capability require design/component evidence; safety and certification are outside this contract.','Adopters must instantiate actual authority, retention, access, effectivity predicates and acceptance criteria.']
    dims=[('identity','BOM revision versus component type versus occurrence.'),('lifecycle','Baseline approval, revision and retirement.'),('relationships','COMPOSE product type and referenced design/variant masters.'),('temporal','Applicable versus recorded and approved time.'),('provenance','Quantity overrides and transformation evidence.'),('ownership','Composition owner versus component master and custodian.'),('validation','Cycles, unresolved references and acceptance fixtures as proposed requirements.'),('access','Scoped disclosure with explicit withheld branches.'),('interoperability','Occurrence preservation, view transformation and semantic losses.'),('direct properties','Qualified nominal properties, not observed item state.'),('recognition','Features, designators and footprint references with ambiguity.'),('capabilities','Functional contribution and evidence-limited compatibility.'),('retention','Historical dependency interpretation and holds.')]
    coverage=dict(claim='Proposed source-grounded reusable engineering-composition information contract, not exhaustive industry coverage or operational conformance.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dims]+[dict(dimension='Executable conformance',status='gap',notes='Nested schema, solver and real-product fixtures deferred.')],known_omissions=omissions,conflicts=[],regional_assumptions=['Owning Dimension must declare contract, sector and jurisdiction requirements; no legal or manufacturing authorization inferred.'],adversarial_checks=['Reject component types conflated with installed serial items.','Reject row merging that destroys repeated occurrence identity.','Reject unknown quantities interpreted as zero or incompatible units multiplied.','Reject every alternate counted as simultaneously selected.','Distinguish group graph cycles from selected graph; stop bounded traversal.','Reject nominal aggregate property as measured safety or capability proof.','Reject silent latest revision, unauthorized disclosure or stale-base update.'])
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
